import{_ as r,o as t,c as o,a2 as e}from"./chunks/framework.ost63GJL.js";const d=JSON.parse('{"title":"企业会计制度（财会〔2000〕25号）","description":"","frontmatter":{"title":"企业会计制度（财会〔2000〕25号）"},"headers":[],"relativePath":"accounting/oe/car/00.md","filePath":"accounting/oe/car/00.md","lastUpdated":null}'),n={name:"accounting/oe/car/00.md"};function s(p,a,l,i,h,g){return t(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="企业会计制度-财会〔2000〕25号" tabindex="-1">企业会计制度（财会〔2000〕25号） <a class="header-anchor" href="#企业会计制度-财会〔2000〕25号" aria-label="Permalink to &quot;企业会计制度（财会〔2000〕25号）&quot;">​</a></h1><h2 id="发文信息" tabindex="-1">发文信息 <a class="header-anchor" href="#发文信息" aria-label="Permalink to &quot;发文信息&quot;">​</a></h2><ul><li><strong>发文机关</strong>：财政部</li><li><strong>发布日期</strong>：2000-12-29</li><li><strong>生效日期</strong>：2001-01-01</li><li><strong>时效性</strong>：现行有效</li><li><strong>文号</strong>：财会〔2000〕25号</li><li><strong>原文链接</strong>：<a href="https://www.mof.gov.cn/" target="_blank" rel="noreferrer">财政部</a></li></ul><h2 id="第一章-总则" tabindex="-1">第一章 总则 <a class="header-anchor" href="#第一章-总则" aria-label="Permalink to &quot;第一章 总则&quot;">​</a></h2><p><strong>第一条</strong>　为了规范企业的会计核算，真实、完整地提供会计信息，根据《中华人民共和国会计法》及国家其他有关法律和法规，制定本制度。</p><p><strong>第二条</strong>　除不对外筹集资金、经营规模较小的企业，以及金融保险企业以外，在中华人民共和国境内设立的企业（含公司，下同），执行本制度。</p><p><strong>第三条</strong>　企业应当根据有关会计法律、行政法规和本制度的规定，在不违反本制度的前提下，结合本企业的具体情况，制定适合于本企业的会计核算办法。</p><p><strong>第四条</strong>　企业填制会计凭证、登记会计账簿、管理会计档案等要求，按照《中华人民共和国会计法》、《会计基础工作规范》和《会计档案管理办法》的规定执行。</p><p><strong>第五条</strong>　会计核算应当以企业发生的各项交易或事项为对象，记录和反映企业本身的各项生产经营活动。</p><p><strong>第六条</strong>　会计核算应当以企业持续、正常的生产经营活动为前提。</p><p><strong>第七条</strong>　会计核算应当划分会计期间，分期结算账目和编制财务会计报告。会计期间分为年度、半年度、季度和月度。年度、半年度、季度和月度均按公历起讫日期确定。半年度、季度和月度均称为会计中期。</p><p>本制度所称的期末和定期，是指月末、季末、半年末和年末。</p><p><strong>第八条</strong>　企业的会计核算以人民币为记账本位币。</p><p>业务收支以人民币以外的货币为主的企业，可以选定其中一种货币作为记账本位币，但是编报的财务会计报告应当折算为人民币。</p><p>在境外设立的中国企业向国内报送的财务会计报告，应当折算为人民币。</p><p><strong>第九条</strong>　企业的会计记账采用借贷记账法。</p><p><strong>第十条</strong>　会计记录的文字应当使用中文。在民族自治地方，会计记录可以同时使用当地通用的一种民族文字。在中华人民共和国境内的外商投资企业、外国企业和其他外国组织的会计记录可以同时使用一种外国文字。</p><p><strong>第十一条</strong>　企业在会计核算时，应当遵循以下基本原则：</p><p>（一）会计核算应当以实际发生的交易或事项为依据，如实反映企业的财务状况、经营成果和现金流量。</p><p>（二）企业应当按照交易或事项的经济实质进行会计核算，而不应当仅仅按照它们的法律形式作为会计核算的依据。</p><p>（三）企业提供的会计信息应当能够反映企业的财务状况、经营成果和现金流量，以满足会计信息使用者的需要。</p><p>（四）企业的会计核算方法前后各期应当保持一致，不得随意变更。如有必要变更，应当将变更的内容和理由、变更的累积影响数，以及累积影响数不能合理确定的理由等，在会计报表附注中予以说明。</p><p>（五）企业的会计核算应当按照规定的会计处理方法进行，会计指标应当口径一致、相互可比。</p><p>（六）企业的会计核算应当及时进行，不得提前或延后。</p><p>（七）企业的会计核算和编制的财务会计报告应当清晰明了，便于理解和利用。</p><p>（八）企业的会计核算应当以权责发生制为基础。凡是当期已经实现的收入和已经发生或应当负担的费用，不论款项是否收付，都应当作为当期的收入和费用；凡是不属于当期的收入和费用，即使款项已在当期收付，也不应当作为当期的收入和费用。</p><p>（九）企业在进行会计核算时，收入与其成本、费用应当相互配比，同一会计期间内的各项收入和与其相关的成本、费用，应当在该会计期间内确认。</p><p>（十）企业的各项财产在取得时应当按照实际成本计量。其后，各项财产如果发生减值，应当按照本制度规定计提相应的减值准备。除法律、行政法规和国家统一的会计制度另有规定者外，企业一律不得自行调整其账面价值。</p><p>（十一）企业的会计核算应当合理划分收益性支出与资本性支出的界限。凡支出的效益仅及于本年度（或一个营业周期）的，应当作为收益性支出；凡支出的效益及于几个会计年度（或几个营业周期）的，应当作为资本性支出。</p><p>（十二）企业在进行会计核算时，应当遵循谨慎性原则的要求，不得多计资产或收益、少计负债或费用，但不得计提秘密准备。</p><p>（十三）企业的会计核算应当遵循重要性原则的要求，在会计核算过程中对交易或事项应当区别其重要程度，采用不同的核算方式。对资产、负债、损益等有较大影响，并进而影响财务会计报告使用者据以作出合理判断的重要会计事项，必须按照规定的会计方法和程序进行处理，并在财务会计报告中予以充分、准确地披露；对于次要的会计事项，在不影响会计信息真实性和不至于误导财务会计报告使用者作出正确判断的前提下，可适当简化处理。</p><h2 id="第二章-资产-概述" tabindex="-1">第二章 资产（概述） <a class="header-anchor" href="#第二章-资产-概述" aria-label="Permalink to &quot;第二章 资产（概述）&quot;">​</a></h2><p><strong>第十二条</strong>　资产，是指过去的交易、事项形成并由企业拥有或者控制的资源，该资源预期会给企业带来经济利益。</p><p><strong>第十三条</strong>　企业的资产应按流动性分为流动资产、长期投资、固定资产、无形资产和其他资产。</p><blockquote><p>本章后续各节（流动资产、长期投资、固定资产、无形资产和其他资产、资产减值）详细规定了各项资产的确认、计量与核算原则，具体条文请参考<a href="https://www.mof.gov.cn/" target="_blank" rel="noreferrer">财政部原文链接</a>。</p></blockquote><h2 id="第三章-负债-概述" tabindex="-1">第三章 负债（概述） <a class="header-anchor" href="#第三章-负债-概述" aria-label="Permalink to &quot;第三章 负债（概述）&quot;">​</a></h2><p><strong>第六十六条</strong>　负债，是指过去的交易、事项形成的现时义务，履行该义务预期会导致经济利益流出企业。</p><p><strong>第六十七条</strong>　企业的负债应按其流动性，分为流动负债和长期负债。</p><h2 id="第四章-所有者权益-概述" tabindex="-1">第四章 所有者权益（概述） <a class="header-anchor" href="#第四章-所有者权益-概述" aria-label="Permalink to &quot;第四章 所有者权益（概述）&quot;">​</a></h2><p><strong>第七十九条</strong>　所有者权益，是指所有者在企业资产中享有的经济利益，其金额为资产减去负债后的余额。所有者权益包括实收资本（或者股本）、资本公积、盈余公积和未分配利润等。</p><h2 id="第五章-收入-概述" tabindex="-1">第五章 收入（概述） <a class="header-anchor" href="#第五章-收入-概述" aria-label="Permalink to &quot;第五章 收入（概述）&quot;">​</a></h2><p><strong>第八十四条</strong>　收入，是指企业在销售商品、提供劳务及让渡资产使用权等日常活动中所形成的经济利益的总流入，包括主营业务收入和其他业务收入。</p><h2 id="第六章-成本和费用-概述" tabindex="-1">第六章 成本和费用（概述） <a class="header-anchor" href="#第六章-成本和费用-概述" aria-label="Permalink to &quot;第六章 成本和费用（概述）&quot;">​</a></h2><p><strong>第九十九条</strong>　费用，是指企业为销售商品、提供劳务等日常活动所发生的经济利益的流出；成本，是指企业为生产产品、提供劳务而发生的各种耗费。</p><h2 id="第七章-利润及利润分配-概述" tabindex="-1">第七章 利润及利润分配（概述） <a class="header-anchor" href="#第七章-利润及利润分配-概述" aria-label="Permalink to &quot;第七章 利润及利润分配（概述）&quot;">​</a></h2><p><strong>第一百零六条</strong>　利润，是指企业在一定会计期间的经营成果，包括营业利润、利润总额和净利润。</p><h2 id="第八章-第十三章" tabindex="-1">第八章~第十三章 <a class="header-anchor" href="#第八章-第十三章" aria-label="Permalink to &quot;第八章~第十三章&quot;">​</a></h2><p>涵盖非货币性交易、外币业务、会计调整、或有事项、关联方关系及其交易、财务会计报告等制度内容，全文详见财政部发布的原文。</p><h2 id="第十四章-附则" tabindex="-1">第十四章 附则 <a class="header-anchor" href="#第十四章-附则" aria-label="Permalink to &quot;第十四章 附则&quot;">​</a></h2><p><strong>第一百六十条</strong>　本制度自2001年1月1日起施行。</p><hr><blockquote><p>说明：本页为《企业会计制度》（财会〔2000〕25号）的章节框架性摘要，全文约 39897 字。完整正文请参考 <a href="https://www.mof.gov.cn/" target="_blank" rel="noreferrer">财政部官网</a> 或 <a href="https://docs.maoyanqing.com/accounting/oe/car/00.html" target="_blank" rel="noreferrer">审计文库原站</a>。</p></blockquote>',52)])])}const u=r(n,[["render",s]]);export{d as __pageData,u as default};
